-- Coach d'Expression Écrite (/tef-irn/writing) : 5 sujets par triplet
-- (section x niveau x type_texte) -> 2 x 3 x 4 x 5 = 120 sujets actifs.
-- Ajoute 108 sujets aux 12 existants. Formats inchangés :
--   Section A = 40 mots min. / 600 s ; Section B = 100 mots min. / 1200 s.
-- Idempotent : pas de contrainte d'unicité sur la table, on dédoublonne
-- sur (section, level, type_texte, title).

INSERT INTO public.writing_exam_scenarios
  (section, level, type_texte, title, sujet, min_words, duration_seconds)
SELECT v.section, v.level, v.type_texte, v.title, v.sujet, v.min_words, v.duration_seconds
FROM (VALUES
  ('A', 'A2', 'message_informatif', 'Cours de français annulé', 'Votre cours de français du jeudi soir est annulé cette semaine. Écrivez un message à un(e) camarade de classe pour le/la prévenir et lui indiquer la date du prochain cours.', 40, 600),
  ('A', 'A2', 'message_informatif', 'Nouveau travail', 'Vous commencez un nouveau travail lundi prochain. Écrivez un message à un(e) ami(e) pour lui annoncer la nouvelle et lui décrire vos horaires et votre lieu de travail.', 40, 600),
  ('A', 'A2', 'lettre_formelle', 'Inscription à la médiathèque', 'Vous voulez vous inscrire à la médiathèque de votre ville. Écrivez un message au service d''accueil pour demander les horaires d''ouverture et les documents nécessaires.', 40, 600),
  ('A', 'A2', 'lettre_formelle', 'Absence de votre enfant', 'Votre enfant est malade et ne peut pas aller à l''école demain. Écrivez un message à son enseignant(e) pour prévenir de son absence et demander les devoirs à faire.', 40, 600),
  ('A', 'A2', 'lettre_formelle', 'Rendez-vous médical', 'Vous ne pouvez pas aller à votre rendez-vous chez le médecin jeudi. Écrivez un message au secrétariat du cabinet pour l''annuler et demander un autre rendez-vous la semaine suivante.', 40, 600),
  ('A', 'A2', 'lettre_formelle', 'Remise des clés', 'Vous emménagez dans un nouvel appartement le mois prochain. Écrivez un message à l''agence immobilière pour demander le jour et l''heure de la remise des clés.', 40, 600),
  ('A', 'A2', 'lettre_formelle', 'Cours de natation', 'La mairie propose des cours de natation pour adultes. Écrivez un message au service des sports pour demander les jours des cours, le prix et comment s''inscrire.', 40, 600),
  ('A', 'A2', 'lettre_reclamation', 'Colis non livré', 'Vous avez commandé un colis sur Internet il y a deux semaines, mais vous ne l''avez pas reçu. Écrivez un message au service client pour signaler le problème et demander une solution.', 40, 600),
  ('A', 'A2', 'lettre_reclamation', 'Chauffage en panne', 'Le chauffage de votre appartement ne fonctionne plus depuis trois jours. Écrivez un message à votre propriétaire pour décrire le problème et demander une réparation rapide.', 40, 600),
  ('A', 'A2', 'lettre_reclamation', 'Facture trop élevée', 'Votre facture d''électricité de ce mois est beaucoup plus élevée que d''habitude. Écrivez un message à votre fournisseur pour signaler le problème et demander une vérification.', 40, 600),
  ('A', 'A2', 'lettre_reclamation', 'Bus en retard', 'Le bus que vous prenez chaque matin pour aller au travail arrive souvent en retard. Écrivez un message à la compagnie de transport pour expliquer le problème et demander un changement.', 40, 600),
  ('A', 'A2', 'lettre_reclamation', 'Repas de cantine', 'Votre enfant n''a pas eu de repas à la cantine lundi, alors que vous aviez payé. Écrivez un message au service scolaire de la mairie pour signaler le problème et demander une explication.', 40, 600),
  ('A', 'A2', 'texte_argumentatif', 'Marché du dimanche', 'La mairie demande l''avis des habitants : faut-il créer un marché le dimanche matin dans votre quartier ? Écrivez un message sur son site pour donner votre avis avec une ou deux raisons simples.', 40, 600),
  ('A', 'A2', 'texte_argumentatif', 'Sortie de fin d''année', 'Votre classe de français prépare une sortie : visiter un musée ou faire un pique-nique. Écrivez un message à votre professeur(e) pour dire ce que vous préférez et pourquoi.', 40, 600),
  ('A', 'A2', 'texte_argumentatif', 'Vélo ou voiture', 'Un(e) ami(e) hésite entre acheter un vélo ou une voiture pour aller au travail en ville. Écrivez-lui un message pour lui donner votre conseil et expliquer simplement votre choix.', 40, 600),
  ('A', 'A2', 'texte_argumentatif', 'Cantine ou tickets', 'Votre entreprise demande aux salariés s''ils préfèrent une cantine ou des tickets restaurant. Écrivez un message à votre responsable pour donner votre avis avec une ou deux raisons.', 40, 600),
  ('A', 'A2', 'texte_argumentatif', 'Aire de jeux', 'La mairie veut construire une aire de jeux pour enfants dans votre rue. Écrivez un message sur le forum du quartier pour dire si vous êtes d''accord et expliquer pourquoi.', 40, 600),
  ('A', 'B1', 'message_informatif', 'Départ pour une autre ville', 'Vous allez déménager dans une autre ville pour votre travail. Écrivez un message à vos ami(e)s pour annoncer la nouvelle, expliquer ce changement et les inviter à une soirée d''au revoir.', 40, 600),
  ('A', 'B1', 'message_informatif', 'Covoiturage pour un concert', 'Vous organisez un covoiturage pour aller à un concert avec des collègues. Écrivez-leur un message pour expliquer l''organisation : horaire, lieu de rendez-vous et partage des frais.', 40, 600),
  ('A', 'B1', 'message_informatif', 'Remplacement pendant les congés', 'Vous partez deux semaines en congé et un(e) collègue va vous remplacer. Écrivez-lui un message pour présenter les tâches urgentes, les contacts importants et votre date de retour.', 40, 600),
  ('A', 'B1', 'message_informatif', 'Collecte de vêtements', 'Vous êtes bénévole dans une association qui organise une collecte de vêtements. Écrivez un message aux habitants de votre immeuble pour présenter l''action, son but et comment participer.', 40, 600),
  ('A', 'B1', 'lettre_formelle', 'Formation professionnelle', 'Vous souhaitez suivre une formation professionnelle proposée par votre ville. Écrivez un message à l''organisme de formation pour présenter votre situation, votre motivation et demander les conditions d''inscription.', 40, 600),
  ('A', 'B1', 'lettre_formelle', 'Horaires aménagés', 'Vous aimeriez modifier vos horaires de travail pour accompagner votre enfant à l''école. Écrivez un message à votre responsable pour expliquer votre situation et proposer une solution.', 40, 600),
  ('A', 'B1', 'lettre_formelle', 'Place en crèche', 'Vous cherchez une place en crèche pour votre enfant. Écrivez un message au service petite enfance de la mairie pour présenter votre situation familiale et demander comment déposer un dossier.', 40, 600),
  ('A', 'B1', 'lettre_formelle', 'Réservation d''une salle', 'Votre association veut organiser une réunion publique. Écrivez un message à la mairie pour réserver une salle, en précisant la date, le nombre de participants et le matériel nécessaire.', 40, 600),
  ('A', 'B1', 'lettre_reclamation', 'Train annulé', 'Votre train a été annulé et vous avez dû acheter un autre billet. Écrivez un message à la compagnie ferroviaire pour raconter ce qui s''est passé et demander un remboursement.', 40, 600),
  ('A', 'B1', 'lettre_reclamation', 'Travaux non terminés', 'Une entreprise devait finir la rénovation de votre salle de bains il y a un mois. Écrivez-lui un message pour exposer le problème, rappeler vos accords et demander une date de fin des travaux.', 40, 600),
  ('A', 'B1', 'lettre_reclamation', 'Connexion Internet coupée', 'Votre connexion Internet est coupée plusieurs fois par jour depuis deux semaines. Écrivez un message à votre opérateur pour décrire le problème, ses conséquences et demander une intervention.', 40, 600),
  ('A', 'B1', 'lettre_reclamation', 'Demande sans réponse', 'Vous attendez depuis trois mois une réponse à votre demande de carte de stationnement résident. Écrivez un message au service concerné pour rappeler votre demande et exprimer votre mécontentement.', 40, 600),
  ('A', 'B1', 'lettre_reclamation', 'Cours de danse annulés', 'Vous avez payé des cours de danse pour l''année, mais plusieurs séances ont été annulées sans prévenir. Écrivez un message à l''école de danse pour vous plaindre et proposer une solution.', 40, 600),
  ('A', 'B1', 'texte_argumentatif', 'Téléphones au collège', 'Le journal de votre ville demande l''avis des lecteurs : faut-il interdire les téléphones portables au collège ? Écrivez un court message pour donner votre opinion et la justifier avec deux arguments.', 40, 600),
  ('A', 'B1', 'texte_argumentatif', 'Jardin ou terrain de sport', 'Un terrain vide de votre quartier pourrait devenir un jardin partagé ou un terrain de sport. Écrivez un message sur le forum des habitants pour défendre votre choix avec des arguments précis.', 40, 600),
  ('A', 'B1', 'texte_argumentatif', 'Semaine de quatre jours', 'Votre entreprise pense passer à la semaine de quatre jours. Écrivez un message à vos collègues pour donner votre avis, en présentant un avantage et un inconvénient.', 40, 600),
  ('A', 'B1', 'texte_argumentatif', 'Centre-ville sans voitures', 'La mairie propose de fermer le centre-ville aux voitures le samedi. Écrivez un message sur le site de la mairie pour dire si vous êtes pour ou contre et expliquer pourquoi.', 40, 600),
  ('A', 'B1', 'texte_argumentatif', 'Cours ou application', 'Un(e) ami(e) qui vient d''arriver en France hésite entre suivre des cours de français ou apprendre seul(e) avec une application. Écrivez-lui un message pour le/la conseiller et justifier votre avis.', 40, 600),
  ('A', 'B2', 'message_informatif', 'Réunion reportée', 'Vous animez une réunion d''équipe qui doit être reportée à cause d''un imprévu. Écrivez un message à vos collègues pour expliquer la situation, ses conséquences sur le projet et la nouvelle organisation.', 40, 600),
  ('A', 'B2', 'message_informatif', 'Assemblée de copropriété', 'Vous avez assisté à l''assemblée générale de votre copropriété à la place de votre voisin. Écrivez-lui un message pour résumer les principales décisions et leurs conséquences pour les habitants.', 40, 600),
  ('A', 'B2', 'message_informatif', 'Week-end en montagne', 'Vous organisez un week-end en montagne pour un groupe d''amis. Écrivez-leur un message pour présenter le programme, les informations pratiques et les précautions à prendre.', 40, 600),
  ('A', 'B2', 'message_informatif', 'Portes ouvertes du club', 'Votre club de sport organise une journée portes ouvertes. Écrivez un message aux adhérents pour présenter l''événement, préciser le rôle attendu des bénévoles et les modalités d''inscription.', 40, 600),
  ('A', 'B2', 'message_informatif', 'Collecte de sang', 'Une collecte de sang aura lieu dans votre commune la semaine prochaine. Écrivez un message aux habitants de votre immeuble pour présenter l''initiative, expliquer son utilité et les conditions pour donner.', 40, 600),
  ('A', 'B2', 'lettre_formelle', 'Candidature spontanée', 'Vous souhaitez travailler dans une entreprise de votre région qui ne publie pas d''offre. Écrivez un message au service des ressources humaines pour présenter votre profil, vos compétences et votre motivation.', 40, 600),
  ('A', 'B2', 'lettre_formelle', 'Dérogation scolaire', 'Vous souhaitez inscrire votre enfant dans une école qui n''est pas celle de votre secteur. Écrivez un message au service scolaire pour justifier votre demande de dérogation de façon argumentée.', 40, 600),
  ('A', 'B2', 'lettre_formelle', 'Formation financée', 'Vous voulez suivre une formation financée par votre employeur. Écrivez un message à votre responsable pour présenter la formation, expliquer ce qu''elle apportera à l''équipe et proposer une organisation.', 40, 600),
  ('A', 'B2', 'lettre_formelle', 'Boîte à livres', 'Vous souhaitez installer une boîte à livres dans votre quartier. Écrivez un message au conseil de quartier pour présenter le projet, ses avantages et les moyens de le réaliser.', 40, 600),
  ('A', 'B2', 'lettre_formelle', 'Départ du logement', 'Vous quittez votre logement à la suite d''une mutation professionnelle. Écrivez un message à votre propriétaire pour annoncer votre départ, préciser les dates et organiser l''état des lieux de sortie.', 40, 600),
  ('A', 'B2', 'lettre_reclamation', 'Dégât des eaux', 'Votre assurance refuse de rembourser un dégât des eaux dans votre appartement. Écrivez un message au service client pour contester cette décision en rappelant les faits et les termes de votre contrat.', 40, 600),
  ('A', 'B2', 'lettre_reclamation', 'Vol très en retard', 'Votre vol a eu plus de cinq heures de retard et vous avez manqué un rendez-vous important. Écrivez un message à la compagnie aérienne pour exposer les conséquences et demander une indemnisation.', 40, 600),
  ('A', 'B2', 'lettre_reclamation', 'Double prélèvement', 'Votre banque a prélevé deux fois le même montant sur votre compte, qui s''est retrouvé à découvert. Écrivez un message à votre conseiller pour exposer le problème et demander réparation.', 40, 600),
  ('A', 'B2', 'lettre_reclamation', 'Chantier trop matinal', 'Un chantier près de chez vous commence tous les jours à 6 heures du matin. Écrivez un message à l''entreprise responsable pour décrire la gêne et demander le respect des horaires autorisés.', 40, 600),
  ('A', 'B2', 'lettre_reclamation', 'Formation décevante', 'Vous avez payé une formation en ligne dont le contenu ne correspond pas à la description. Écrivez un message à l''organisme pour exprimer votre insatisfaction et demander un remboursement partiel.', 40, 600),
  ('A', 'B2', 'texte_argumentatif', 'Transports gratuits', 'Votre ville envisage de rendre les transports en commun gratuits. Écrivez un message au journal local pour prendre position en présentant vos arguments et en répondant à une objection.', 40, 600),
  ('A', 'B2', 'texte_argumentatif', 'Uniforme scolaire', 'Le conseil d''école débat de l''introduction d''un uniforme scolaire. Écrivez un message aux autres parents pour défendre votre position en nuançant vos arguments.', 40, 600),
  ('A', 'B2', 'texte_argumentatif', 'Centre commercial', 'Un grand centre commercial va ouvrir à la périphérie de votre ville. Écrivez un message sur le forum des habitants pour donner votre avis sur ses conséquences pour les petits commerces du centre.', 40, 600),
  ('A', 'B2', 'texte_argumentatif', 'Langue et intégration', 'Un collègue affirme qu''apprendre la langue du pays d''accueil est la condition la plus importante pour s''intégrer. Écrivez-lui un message pour réagir en exposant un point de vue argumenté.', 40, 600),
  ('A', 'B2', 'texte_argumentatif', 'Tourisme estival', 'Votre région accueille de plus en plus de touristes chaque été. Écrivez un message au journal régional pour présenter les avantages et les inconvénients de ce phénomène et donner votre opinion.', 40, 600),
  ('B', 'A2', 'message_informatif', 'Mon nouveau quartier', 'Vous venez d''emménager dans un nouveau quartier. Écrivez un message à un(e) ami(e) pour décrire votre logement, les commerces et les transports près de chez vous.', 100, 1200),
  ('B', 'A2', 'message_informatif', 'Première semaine de cours', 'Vous avez commencé un cours du soir. Écrivez un message à un(e) ami(e) pour raconter votre première semaine : les autres élèves, le professeur et ce que vous avez appris.', 100, 1200),
  ('B', 'A2', 'message_informatif', 'Retour de vacances', 'Vous revenez de vacances. Écrivez un message à un(e) collègue pour raconter où vous êtes allé(e), ce que vous avez fait et ce que vous avez aimé.', 100, 1200),
  ('B', 'A2', 'message_informatif', 'Anniversaire réussi', 'Vous avez organisé l''anniversaire de votre enfant le week-end dernier. Écrivez un message à un(e) ami(e) absent(e) pour raconter la fête : les invités, les activités et le repas.', 100, 1200),
  ('B', 'A2', 'message_informatif', 'Visite de votre ville', 'Un(e) ami(e) vient vous voir le mois prochain. Écrivez-lui un message pour présenter votre ville : les lieux à visiter, les restaurants et comment venir chez vous.', 100, 1200),
  ('B', 'A2', 'lettre_formelle', 'Carte de transport perdue', 'Vous avez perdu votre carte d''abonnement de transport. Écrivez un message à l''agence de transport pour expliquer quand et où vous l''avez perdue et demander une nouvelle carte.', 100, 1200),
  ('B', 'A2', 'lettre_formelle', 'Inscription à l''école', 'Votre famille vient d''arriver dans la ville et votre enfant doit aller à l''école. Écrivez un message à la direction de l''école pour présenter votre enfant et demander un rendez-vous.', 100, 1200),
  ('B', 'A2', 'lettre_formelle', 'Cours de français pour adultes', 'Vous cherchez des cours de français pour adultes. Écrivez un message à une association de votre ville pour vous présenter, expliquer votre niveau et demander les jours et les prix des cours.', 100, 1200),
  ('B', 'A2', 'lettre_formelle', 'Jardin familial', 'La mairie propose des petits jardins à louer aux habitants. Écrivez un message au service des espaces verts pour vous présenter, expliquer pourquoi vous voulez un jardin et demander les conditions.', 100, 1200),
  ('B', 'A2', 'lettre_formelle', 'Devenir bénévole', 'Vous voulez devenir bénévole dans une banque alimentaire. Écrivez un message à l''association pour vous présenter, dire quand vous êtes disponible et ce que vous aimez faire.', 100, 1200),
  ('B', 'A2', 'lettre_reclamation', 'Séjour à l''hôtel', 'Vous avez passé deux nuits dans un hôtel et la chambre était sale et bruyante. Écrivez un message au directeur de l''hôtel pour raconter votre séjour et demander une réduction.', 100, 1200),
  ('B', 'A2', 'lettre_reclamation', 'Lave-linge en panne', 'Vous avez acheté un lave-linge il y a un mois et il ne fonctionne déjà plus. Écrivez un message au magasin pour décrire votre achat, le problème et demander une réparation.', 100, 1200),
  ('B', 'A2', 'lettre_reclamation', 'Ascenseur en panne', 'L''ascenseur de votre immeuble est en panne depuis deux semaines. Écrivez un message au gestionnaire de l''immeuble pour décrire les difficultés des habitants et demander une réparation.', 100, 1200),
  ('B', 'A2', 'lettre_reclamation', 'Repas livré froid', 'Vous avez commandé un repas à livrer, mais il est arrivé froid, en retard et incomplet. Écrivez un message au restaurant pour raconter ce qui s''est passé et demander un remboursement.', 100, 1200),
  ('B', 'A2', 'lettre_reclamation', 'Vestiaires de la piscine', 'Vous allez souvent à la piscine municipale, mais les vestiaires sont sales depuis plusieurs semaines. Écrivez un message à la mairie pour décrire la situation et demander un meilleur nettoyage.', 100, 1200),
  ('B', 'A2', 'texte_argumentatif', 'Ville ou campagne', 'Un magazine demande à ses lecteurs : préférez-vous vivre en ville ou à la campagne ? Écrivez un texte pour donner votre préférence et l''expliquer avec des exemples de votre vie.', 100, 1200),
  ('B', 'A2', 'texte_argumentatif', 'Pourquoi faire du sport', 'Le journal de votre quartier demande à ses lecteurs pourquoi faire du sport. Écrivez un texte pour donner votre avis et raconter ce que le sport vous apporte, ou pourquoi vous n''en faites pas.', 100, 1200),
  ('B', 'A2', 'texte_argumentatif', 'Cuisiner ou acheter', 'Sur un forum, des personnes discutent : faut-il cuisiner à la maison ou acheter des plats préparés ? Écrivez un texte pour donner votre avis avec des exemples de vos habitudes.', 100, 1200),
  ('B', 'A2', 'texte_argumentatif', 'Voyager seul ou en groupe', 'Un(e) ami(e) prépare un voyage et hésite entre partir seul(e) ou en groupe. Écrivez-lui un texte pour donner votre avis et raconter une expérience personnelle.', 100, 1200),
  ('B', 'A2', 'texte_argumentatif', 'Animal de compagnie', 'Votre famille veut adopter un animal de compagnie. Écrivez un texte pour dire si vous êtes d''accord, quel animal vous préférez et pour quelles raisons.', 100, 1200),
  ('B', 'B1', 'message_informatif', 'Bienvenue dans l''équipe', 'Un nouveau collègue arrive dans votre équipe lundi. Écrivez-lui un message pour lui souhaiter la bienvenue, présenter l''équipe et expliquer le déroulement de sa première journée.', 100, 1200),
  ('B', 'B1', 'message_informatif', 'Vide-grenier du quartier', 'Votre association de quartier organise un vide-grenier. Écrivez un message aux habitants pour présenter l''événement, expliquer comment réserver un stand et rappeler les règles à respecter.', 100, 1200),
  ('B', 'B1', 'message_informatif', 'Fin de stage', 'Vous venez de terminer un stage dans une entreprise. Écrivez un message à un(e) ami(e) pour raconter cette expérience, ce que vous avez appris et vos projets pour la suite.', 100, 1200),
  ('B', 'B1', 'message_informatif', 'Travaux dans l''immeuble', 'Vous représentez les locataires de votre immeuble. Écrivez un message aux habitants pour annoncer des travaux de rénovation, leur durée et leurs conséquences sur la vie quotidienne.', 100, 1200),
  ('B', 'B1', 'message_informatif', 'Garde des enfants', 'Vous partez en déplacement professionnel et votre voisin(e) va garder vos enfants. Écrivez-lui un message pour expliquer leurs habitudes, les horaires d''école et les numéros utiles.', 100, 1200),
  ('B', 'B1', 'lettre_formelle', 'Logement plus grand', 'Vous souhaitez obtenir un logement plus grand pour votre famille. Écrivez une lettre au bailleur social pour présenter votre situation, expliquer vos besoins et demander un changement de logement.', 100, 1200),
  ('B', 'B1', 'lettre_formelle', 'Demande de congé', 'Vous souhaitez prendre trois semaines de congé pour rendre visite à votre famille à l''étranger. Écrivez une lettre à votre employeur pour présenter et justifier votre demande et proposer une organisation.', 100, 1200),
  ('B', 'B1', 'lettre_formelle', 'Matériel pour le club', 'Votre association sportive souhaite acheter du nouveau matériel. Écrivez une lettre à la mairie pour présenter l''association, expliquer le projet et demander une aide financière.', 100, 1200),
  ('B', 'B1', 'lettre_formelle', 'Difficultés en classe', 'Votre enfant rencontre des difficultés en classe. Écrivez une lettre à son enseignant(e) pour décrire la situation, poser vos questions et demander un rendez-vous.', 100, 1200),
  ('B', 'B1', 'lettre_formelle', 'Atelier cuisine du monde', 'Vous voulez proposer un atelier de cuisine du monde au centre social de votre quartier. Écrivez une lettre à la direction pour présenter votre idée, son intérêt pour les habitants et vos disponibilités.', 100, 1200),
  ('B', 'B1', 'lettre_reclamation', 'Voiture de location', 'Au retour d''une voiture de location, l''agence vous a facturé des dommages que vous n''avez pas causés. Écrivez une lettre au service client pour raconter les faits, contester les frais et demander un remboursement.', 100, 1200),
  ('B', 'B1', 'lettre_reclamation', 'Fermeture sans prévenir', 'Votre salle de sport a fermé plusieurs semaines pour travaux sans prévenir ses clients. Écrivez une lettre au responsable pour exprimer votre mécontentement et demander une compensation.', 100, 1200),
  ('B', 'B1', 'lettre_reclamation', 'Meuble endommagé', 'Le meuble que vous avez commandé est arrivé endommagé et le service client ne répond pas. Écrivez une lettre au vendeur pour décrire le problème, rappeler vos démarches et demander une solution rapide.', 100, 1200),
  ('B', 'B1', 'lettre_reclamation', 'Parties communes négligées', 'Les parties communes de votre résidence sont mal entretenues depuis des mois. Écrivez une lettre au gestionnaire de l''immeuble pour décrire la situation, ses conséquences et demander des mesures concrètes.', 100, 1200),
  ('B', 'B1', 'texte_argumentatif', 'Repas végétarien', 'La cantine scolaire de votre ville envisage de proposer un repas végétarien chaque jour. Écrivez un texte pour le site de la mairie afin de donner votre avis et de le justifier par des exemples.', 100, 1200),
  ('B', 'B1', 'texte_argumentatif', 'Travailler pendant ses études', 'Beaucoup de jeunes travaillent pendant leurs études. Écrivez un texte pour un magazine étudiant afin de montrer les avantages et les inconvénients de cette situation et donner votre avis.', 100, 1200),
  ('B', 'B1', 'texte_argumentatif', 'Réseaux sociaux et famille', 'Un magazine demande si les réseaux sociaux aident à garder le contact avec sa famille et ses amis. Écrivez un texte pour donner votre opinion en l''illustrant par des exemples.', 100, 1200),
  ('B', 'B2', 'message_informatif', 'Bilan de projet', 'Vous avez piloté un projet dans votre entreprise. Écrivez un message à votre direction pour présenter le bilan : objectifs atteints, difficultés rencontrées et propositions pour la suite.', 100, 1200),
  ('B', 'B2', 'message_informatif', 'Règlement de la résidence', 'Vous êtes responsable d''une résidence étudiante dont le règlement a changé. Écrivez un message aux résidents pour présenter les nouvelles règles, leurs raisons et leurs conséquences au quotidien.', 100, 1200),
  ('B', 'B2', 'message_informatif', 'Retour de conférence', 'Vous avez assisté à une conférence professionnelle au nom de votre équipe. Écrivez un message à vos collègues pour résumer les idées principales et expliquer ce qu''elles pourraient changer dans votre travail.', 100, 1200),
  ('B', 'B2', 'message_informatif', 'Aide pendant la canicule', 'La mairie lance un dispositif d''aide aux personnes âgées pendant les fortes chaleurs. Écrivez un message dans le journal de l''immeuble pour présenter le dispositif, son utilité et la façon d''y participer.', 100, 1200),
  ('B', 'B2', 'message_informatif', 'Échange scolaire', 'Le collège de votre enfant organise un échange avec une école étrangère. Écrivez un message aux autres parents pour présenter le projet, son intérêt pédagogique et l''organisation prévue.', 100, 1200),
  ('B', 'B2', 'lettre_formelle', 'Création d''entreprise', 'Vous souhaitez créer une petite entreprise de services à domicile. Écrivez une lettre à une banque pour présenter votre projet, démontrer sa viabilité et solliciter un rendez-vous pour un prêt.', 100, 1200),
  ('B', 'B2', 'lettre_formelle', 'Mobilité interne', 'Un poste se libère dans une autre filiale de votre entreprise. Écrivez une lettre aux ressources humaines pour présenter votre candidature et montrer en quoi votre parcours correspond au poste.', 100, 1200),
  ('B', 'B2', 'lettre_formelle', 'Gare peu accessible', 'La gare de votre ville est difficile d''accès pour les personnes à mobilité réduite. Écrivez une lettre au maire pour décrire la situation, en montrer les conséquences et proposer des améliorations.', 100, 1200),
  ('B', 'B2', 'lettre_formelle', 'Partenariat associatif', 'Votre association d''aide aux devoirs cherche un partenaire. Écrivez une lettre à une entreprise locale pour présenter l''association, expliquer l''intérêt d''un partenariat et proposer une rencontre.', 100, 1200),
  ('B', 'B2', 'lettre_reclamation', 'Déménagement raté', 'L''entreprise de déménagement a abîmé plusieurs de vos meubles et refuse toute responsabilité. Écrivez une lettre à sa direction pour exposer les faits, contester sa position et exiger une indemnisation.', 100, 1200),
  ('B', 'B2', 'lettre_reclamation', 'Dépôt de garantie', 'Votre ancien propriétaire refuse de vous rendre votre dépôt de garantie sans raison valable. Écrivez-lui une lettre pour rappeler l''état du logement à votre départ, contester sa décision et demander le remboursement.', 100, 1200),
  ('B', 'B2', 'lettre_reclamation', 'Ligne de bus supprimée', 'La compagnie de transport a supprimé la ligne de bus qui dessert votre quartier. Écrivez une lettre à sa direction pour exposer les conséquences pour les habitants et demander le rétablissement du service.', 100, 1200),
  ('B', 'B2', 'lettre_reclamation', 'Garantie non respectée', 'Votre ordinateur, encore sous garantie, a été renvoyé trois fois en réparation sans succès. Écrivez une lettre au fabricant pour retracer vos démarches, exprimer votre mécontentement et exiger un remplacement.', 100, 1200),
  ('B', 'B2', 'texte_argumentatif', 'IA et devoirs', 'Certains enseignants autorisent les élèves à utiliser l''intelligence artificielle pour leurs devoirs. Écrivez un texte pour le journal de votre ville afin de prendre position, en discutant les avantages et les risques.', 100, 1200),
  ('B', 'B2', 'texte_argumentatif', 'Consommer local', 'Un article affirme qu''acheter des produits locaux est trop cher pour la plupart des familles. Écrivez un texte pour réagir à cette idée en développant une argumentation nuancée et illustrée d''exemples.', 100, 1200),
  ('B', 'B2', 'texte_argumentatif', 'Engagement des jeunes', 'Votre commune souhaite encourager les jeunes à s''engager dans des associations. Écrivez un texte pour le bulletin municipal afin d''expliquer pourquoi cet engagement est utile et comment le favoriser.', 100, 1200)
) AS v(section, level, type_texte, title, sujet, min_words, duration_seconds)
WHERE NOT EXISTS (
  SELECT 1 FROM public.writing_exam_scenarios w
  WHERE w.section = v.section AND w.level = v.level
    AND w.type_texte = v.type_texte AND w.title = v.title
);
